The marked lines are parallel. Find $x$ and give a reason.

[tikz]
\begin{tikzpicture}[x=1cm,y=1cm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\coordinate (P) at (0,1);
\coordinate (Q) at ({-2/tan(55)},-1);
\draw (-2.5,1)--(2.5,1);
\draw (-2.5,-1)--(2.5,-1);
\draw ({-3/tan(55)},-2)--({1/tan(55)},2);
\draw[->] (1.7,1)--(2.1,1);
\draw[->] (1.7,-1)--(2.1,-1);
\draw (P) ++(0:0.45) arc[start angle=0,end angle=55,radius=0.45];
\draw (Q) ++(0:0.45) arc[start angle=0,end angle=55,radius=0.45];
\path (P) ++(27.5:0.85) node {$55^{\circ}$};
\path (Q) ++(27.5:0.85) node {$x$};
\end{tikzpicture}
[/tikz]

